const reviews=[{"id": 1, "product": "핑크 큐피드 케이스", "title": "거울 앞에서도, 익규와 함께", "caption": "손으로 만든 하트 사이로 핑크 큐피드 익규가 빼꼼. 헤드셋과 버건디 컬러에 핑크 케이스가 어우러진 일상 속 거울 사진이에요."}, {"id": 2, "product": "네잎클로버 케이스", "title": "손안에 담은 작은 행운", "caption": "밝은 기기 컬러 위로 또렷하게 보이는 네잎클로버 익규. 투명한 바탕과 초록 포인트를 가까이에서 담아주셨어요."}, {"id": 3, "product": "네잎클로버 케이스", "title": "클로버를 한 손 가득", "caption": "네잎클로버 케이스에 클로버 모양 액세서리를 더한 조합. 익규와 초록 클로버가 나란히 보여 더 풍성한 귀여움을 전해요."}, {"id": 4, "product": "네잎클로버 케이스", "title": "드디어 찾았다 내 평생 폰케이스 진.익.규 🍀", "caption": "사진에 남겨주신 말처럼, 반가운 익규와의 만남. 패키지 속 네잎클로버 케이스와 손에 쥔 작은 행운을 담은 사진이에요."}, {"id": 5, "product": "익규와 함께한 순간", "title": "작은 화면에도 익규 취향", "caption": "작게 접힌 기기에 담긴 네잎클로버 익규. 손목시계와 함께 남긴 깔끔한 일상 사진 속에서도 초록 클로버가 눈에 들어와요."}, {"id": 6, "product": "네잎클로버 케이스", "title": "책상 위로 도착한 행운", "caption": "키보드와 데스크 소품을 배경으로 담아주신 네잎클로버 케이스. 투명한 바탕 위 익규와 ‘행운 잔뜩 받아’ 문구가 함께 보여요."}, {"id": 7, "product": "블루리본 · 네잎클로버", "title": "서로 다른 귀여움을 나란히", "caption": "블루리본과 네잎클로버가 저녁 테이블에서 만났어요. 각기 다른 기기와 디자인에 담긴 익규의 매력을 한 장에서 볼 수 있어요."}, {"id": 8, "product": "핑크 큐피드 케이스", "title": "익규 폰케이스 졸귀", "caption": "사진 속 짧은 한마디에 담긴 귀여움. 반려견 곁에서 핑크 큐피드 케이스를 함께 담아주신 포근한 일상 사진이에요."}, {"id": 9, "product": "핑크 큐피드 케이스", "title": "벚꽃 피는 밤, 익규도 함께", "caption": "밤벚꽃 아래에서 만난 핑크 큐피드 익규. 가득 핀 꽃과 핑크 케이스가 어우러져 봄날의 분위기를 전해줘요."}, {"id": 10, "product": "화들짝 케이스", "title": "초록 사이로 빼꼼, 화들짝 익규", "caption": "초록 식물 사이에서 담아주신 화들짝 케이스. 노란빛 익규와 캐릭터 액세서리가 함께 보여 장난스러운 매력이 더해져요."}];
function reviewCard(r){return `<button class="review-card" data-review="${r.id}" aria-label="${r.product} 고객 사진 크게 보기"><img src="assets/reviews/review-${r.id}.jpg" alt="${r.product} 고객 제공 사진 ${r.id}" loading="lazy"><div class="review-copy"><span>제품명 : ${r.product}</span><small class="photo-story-label">사진 이야기</small><h3>${r.title}</h3><p>${r.caption}</p></div></button>`}
const preview=document.querySelector('#review-preview');if(preview)preview.innerHTML=[reviews[3],reviews[7],reviews[6]].map(reviewCard).join('');
const gallery=document.querySelector('#review-gallery');if(gallery)gallery.innerHTML=reviews.map(reviewCard).join('');
const lightbox=document.createElement('dialog');lightbox.className='photo-lightbox';lightbox.innerHTML='<button class="lightbox-close" aria-label="리뷰 사진 닫기">×</button><img alt=""><p></p>';document.body.append(lightbox);
document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const r=reviews.find(r=>r.id===+b.dataset.review);lightbox.querySelector('img').src=`assets/reviews/review-${r.id}.jpg`;lightbox.querySelector('img').alt=r.product+' 고객 제공 사진';lightbox.querySelector('p').textContent=r.title+'\n\n'+r.caption;lightbox.showModal()});
lightbox.querySelector('button').onclick=()=>lightbox.close();lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});
